create extension if not exists "pgcrypto";
create table if not exists public.projects(id uuid primary key default gen_random_uuid(),title text not null,description text default '',image_url text default '',tech_stack text[] not null default '{}',category text not null default 'fullstack' check(category in('frontend','backend','fullstack')),github_link text default '',live_link text default '',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.admin(id bigint generated by default as identity primary key,user_id uuid not null unique references auth.users(id) on delete cascade,role text not null default 'admin' check(role='admin'),created_at timestamptz not null default now());
create table if not exists public.messages(id bigint generated by default as identity primary key,name text not null,email text not null,subject text default '',message text not null,created_at timestamptz not null default now());
alter table public.projects enable row level security; alter table public.admin enable row level security; alter table public.messages enable row level security;
drop policy if exists projects_public_read on public.projects; create policy projects_public_read on public.projects for select to anon,authenticated using(true);
grant select on public.projects to anon,authenticated;
drop policy if exists admin_read_own on public.admin; create policy admin_read_own on public.admin for select to authenticated using(auth.uid()=user_id);
drop policy if exists projects_admin_insert on public.projects; create policy projects_admin_insert on public.projects for insert to authenticated with check(exists(select 1 from public.admin where user_id=auth.uid() and role='admin'));
drop policy if exists projects_admin_update on public.projects; create policy projects_admin_update on public.projects for update to authenticated using(exists(select 1 from public.admin where user_id=auth.uid() and role='admin')) with check(exists(select 1 from public.admin where user_id=auth.uid() and role='admin'));
drop policy if exists projects_admin_delete on public.projects; create policy projects_admin_delete on public.projects for delete to authenticated using(exists(select 1 from public.admin where user_id=auth.uid() and role='admin'));
drop policy if exists messages_public_insert on public.messages; create policy messages_public_insert on public.messages for insert to anon,authenticated with check(true);
drop policy if exists messages_admin_read on public.messages; create policy messages_admin_read on public.messages for select to authenticated using(exists(select 1 from public.admin where user_id=auth.uid() and role='admin'));
grant select on public.messages to authenticated;
